function neverChangesDirection(nums: number[]): boolean {
  let inc = true, dec = true;
  for (let i = 1; i < nums.length; i++) if (nums[i] < nums[i - 1]) inc = false;
  for (let i = 1; i < nums.length; i++) if (nums[i] > nums[i - 1]) dec = false;
  return inc || dec;
}

